The solution requires modifications to four specific files.

1.  **`pulsesphere/lib/common/include/ps_config.h`:**
    ```c
    // Inside a relevant config struct, e.g., ps_service_config_t
    // ... other fields
    int max_retries;
    int heartbeat_interval_ms; // <<< ADDED LINE
    char* log_file;
    // ... other fields
    ```

2.  **`pulsesphere/lib/common/src/ps_config.c`:**
    ```c
    // Inside the config parsing handler function, e.g., config_handler()
    // ... other strcmp checks
    } else if (strcmp(name, "heartbeat_interval_ms") == 0) {
        pconfig->heartbeat_interval_ms = atoi(value); // <<< ADDED BLOCK
    } else {
        return 0;  /* unknown section/name, error */
    }
    ```

3.  **`pulsesphere/config/ingestion_service.conf`:**
    ```ini
    # ... other config lines
    log_level = info

    # Interval in milliseconds for the main processing loop heartbeat
    heartbeat_interval_ms = 5000 # <<< ADDED LINE
    ```

4.  **`pulsesphere/services/ingestion_service/src/main.c`:**
    ```c
    // Near the top of main(), after config is loaded
    ps_config_t config;
    if (ps_config_load(&config, "../config/ingestion_service.conf") != 0) {
        ps_log_fatal("Failed to load configuration.");
        return 1;
    }
    ps_log_info("Ingestion service configured with heartbeat interval: %d ms", config.heartbeat_interval_ms); // <<< ADDED LINE

    // ... further down, inside the main while loop
    while (1) {
        process_pending_messages();
        // Old line: sleep(5); // Sleep for 5 seconds
        usleep(config.heartbeat_interval_ms * 1000); // <<< MODIFIED LINE
    }
    ```
